WITH daily_sales AS ( SELECT ss.ss_store_sk AS store_sk, ss.ss_sold_date_sk AS sold_date_sk, cd.cd_marital_status AS marital_status, hd.hd_buy_potential AS buy_potential, SUM(ss.ss_net_paid) AS daily_net_paid, SUM(ss.ss_net_profit) AS daily_net_profit FROM store_sales ss INNER JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk INNER JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk GROUP BY ss.ss_store_sk, ss.ss_sold_date_sk, cd.cd_marital_status, hd.hd_buy_potential ), lagged_sales AS ( SELECT store_sk, sold_date_sk, marital_status, buy_potential, daily_net_paid, LAG(daily_net_paid) OVER (PARTITION BY store_sk, marital_status ORDER BY sold_date_sk) AS prev_daily_net_paid, daily_net_profit, ROW_NUMBER() OVER (PARTITION BY store_sk ORDER BY daily_net_paid DESC) AS top_day_rank FROM daily_sales ) SELECT store_sk, sold_date_sk, marital_status, buy_potential, daily_net_paid, prev_daily_net_paid, CASE WHEN prev_daily_net_paid IS NULL THEN NULL ELSE ((daily_net_paid - prev_daily_net_paid) / prev_daily_net_paid) * 100 END AS pct_change_vs_previous_day, daily_net_profit, top_day_rank FROM lagged_sales WHERE top_day_rank <= 3 ORDER BY store_sk, sold_date_sk
